const attempts = new Map<string, number[]>();
const utf8 = new TextEncoder();
const base64url = (bytes: Uint8Array) => btoa(String.fromCharCode(...bytes)).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
const unbase64url = (text: string) => Uint8Array.from(atob(text.replace(/-/g,"+").replace(/_/g,"/")+"===".slice((text.length+3)%4)),c=>c.charCodeAt(0));
const equal = (a:string,b:string) => {const x=utf8.encode(a),y=utf8.encode(b);if(x.length!==y.length)return false;let v=0;for(let i=0;i<x.length;i++)v|=x[i]^y[i];return v===0};
const json = (data:unknown,status=200,headers:Record<string,string>={}) => new Response(JSON.stringify(data),{status,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store",...headers}});
const service = () => {const direct=Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");if(direct)return direct;try{return JSON.parse(Deno.env.get("SUPABASE_SECRET_KEYS")||"{}").default}catch{return undefined}};
const cfg = () => {const url=Deno.env.get("SUPABASE_URL"),key=service();if(!url||!key)throw new Error("Le service RH est en cours de configuration.");return{url:url.replace(/\/$/,""),key}};
async function db(path:string,method="GET",value?:unknown){const c=cfg(),headers:Record<string,string>={apikey:c.key,"Content-Type":"application/json",Prefer:method==="POST"?"return=representation":method==="PATCH"?"return=representation":"count=exact"};if(c.key.startsWith("eyJ"))headers.Authorization=`Bearer ${c.key}`;const r=await fetch(`${c.url}/rest/v1/${path}`,{method,headers,body:value?JSON.stringify(value):undefined});const raw=await r.text();let data;try{data=raw?JSON.parse(raw):null}catch{data=raw}if(!r.ok)throw Object.assign(new Error(typeof data==="object"?(data.message||"Erreur de base de données."):String(data)),{status:r.status});return{data,range:r.headers.get("content-range")}}
const qp=(table:string,params:Record<string,string>)=>`${table}?${new URLSearchParams(params)}`;
const cookie=(req:Request,name:string)=>{const v=(req.headers.get("cookie")||"").split(";").map(x=>x.trim()).find(x=>x.startsWith(`${name}=`));return v?decodeURIComponent(v.slice(name.length+1)):""};
function cookieHeader(value:string,maxAge:number){return`noria_session=${encodeURIComponent(value)}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${maxAge}`}
async function hmac(data:string){const key=await crypto.subtle.importKey("raw",utf8.encode(cfg().key),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return base64url(new Uint8Array(await crypto.subtle.sign("HMAC",key,utf8.encode(data))))}
async function token(payload:Record<string,unknown>){const head=base64url(utf8.encode(JSON.stringify({alg:"HS256",typ:"JWT"}))),body=base64url(utf8.encode(JSON.stringify(payload))),input=`${head}.${body}`;return`${input}.${await hmac(input)}`}
async function claims(req:Request){const raw=cookie(req,"noria_session"),p=raw.split(".");if(p.length!==3)return null;const expected=await hmac(`${p[0]}.${p[1]}`);if(!equal(expected,p[2]))return null;try{const c=JSON.parse(new TextDecoder().decode(unbase64url(p[1])));return c.exp>Date.now()/1000?c:null}catch{return null}}
async function current(req:Request){const c=await claims(req);if(!c?.sub)return null;const {data}=await db(qp("hr_accounts",{select:"employee_id,identifier,role,enabled",employee_id:`eq.${c.sub}`,limit:"1"}));const a=data?.[0];return a?.enabled?{employee_id:a.employee_id,identifier:a.identifier,role:a.role}:null}
async function hashPassword(value:string,salt=crypto.getRandomValues(new Uint8Array(16)),iterations=310000){const key=await crypto.subtle.importKey("raw",utf8.encode(value),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt,iterations},key,256);return`pbkdf2$${iterations}$${base64url(salt)}$${base64url(new Uint8Array(bits))}`}
async function verifyPassword(value:string,stored:string){const [scheme,n,salt,digest]=stored.split("$");if(scheme!=="pbkdf2"||!n||!salt||!digest)return false;return equal(await hashPassword(value,unbase64url(salt),Number(n)),`pbkdf2$${n}$${salt}$${digest}`)}
function workdays(a:string,b:string){let count=0;for(let d=new Date(`${a}T12:00:00`),end=new Date(`${b}T12:00:00`);d<=end;d.setDate(d.getDate()+1))if(d.getDay()!==0&&d.getDay()!==6)count++;return count}
async function readBody(req:Request){const v=await req.text();if(v.length>14000)throw Object.assign(new Error("Requête trop volumineuse."),{status:413});try{return JSON.parse(v||"{}")}catch{throw Object.assign(new Error("Requête invalide."),{status:400})}}
const employeeFields="id,staff_number,first_name,last_name,job_title,department,contract_type,start_date,location,status,leave_balance";
async function dashboard(user:any){const [{data:employees,range},{data:leaves},{data:jobs},{data:profile}]=await Promise.all([
db(qp("employees",{select:employeeFields,status:"eq.active",order:"last_name.asc",limit:"500"})),db(qp("leave_requests",{select:"id,employee_id,leave_type,start_date,end_date,days,status,created_at",order:"start_date.asc",limit:"500"})),db(qp("job_postings",{select:"id,status",status:"eq.open",limit:"500"})),db(qp("employees",{select:"id,first_name,last_name,role,leave_balance",id:`eq.${user.employee_id}`,limit:"1"}))]);const today=new Date().toISOString().slice(0,10),limit=new Date(Date.now()+45*86400000).toISOString().slice(0,10),mine=leaves.filter((x:any)=>x.employee_id===user.employee_id),visible=user.role==="admin"||user.role==="manager"?leaves:mine,approved=visible.filter((x:any)=>x.status==="approved");const upcoming=approved.filter((x:any)=>x.start_date>=today&&x.start_date<=limit).slice(0,5).map((l:any)=>({...l,...employees.find((e:any)=>e.id===l.employee_id)}));return{summary:{employee_count:employees.length,on_leave_today:approved.filter((x:any)=>x.start_date<=today&&x.end_date>=today).length,pending_leave:visible.filter((x:any)=>x.status==="pending").length,open_positions:jobs.length,leave_balance:profile?.[0]?.leave_balance??0,my_pending:mine.filter((x:any)=>x.status==="pending").length,my_approved:mine.filter((x:any)=>x.status==="approved").length,upcoming_leaves:upcoming},employees:user.role==="admin"||user.role==="manager"?employees:[],leaves:visible.map((l:any)=>({...l,...employees.find((e:any)=>e.id===l.employee_id)}))}}
async function servePage(req:Request){const nonce=base64url(crypto.getRandomValues(new Uint8Array(18))),endpoint=new URL(req.url).pathname,configScript=`<script nonce="${nonce}">window.NORIA_CONFIG={endpoint:${JSON.stringify(endpoint)},apiKey:${JSON.stringify(PUBLIC_KEY)}};</script>`,html=PAGE.replace('<link rel="stylesheet" href="/styles.css">',`<style nonce="${nonce}">${STYLES}</style>`).replace('<script src="/app.js" defer></script>',`${configScript}<script nonce="${nonce}">${APP}</script>`);return new Response(html,{headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff","X-Frame-Options":"DENY","Referrer-Policy":"strict-origin-when-cross-origin","X-Robots-Tag":"noindex, nofollow, noarchive","Content-Security-Policy":`default-src 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'`}})}

Deno.serve(async(req:Request)=>{try{const url=new URL(req.url),action=url.searchParams.get("action");if(!action&&req.method==="GET")return await servePage(req);
if(action==="login"&&req.method==="POST"){const b=await readBody(req),identifier=String(b.identifier||"").trim().toUpperCase(),password=String(b.password||"");if(!identifier||!password)return json({error:"Saisissez votre identifiant et votre mot de passe."},400);const ip=req.headers.get("x-forwarded-for")?.split(",")[0]||"unknown",k=`${ip}:${identifier}`,now=Date.now(),recent=(attempts.get(k)||[]).filter(x=>now-x<600000);if(recent.length>=8)return json({error:"Trop de tentatives. Réessayez dans quelques minutes."},429);recent.push(now);attempts.set(k,recent);const {data}=await db(qp("hr_accounts",{select:"employee_id,identifier,password_hash,role,enabled",identifier:`eq.${identifier}`,limit:"1"}));const a=data?.[0];if(!a?.enabled||!await verifyPassword(password,a.password_hash))return json({error:"Identifiant ou mot de passe incorrect."},401);attempts.delete(k);const {data:p}=await db(qp("employees",{select:"first_name,last_name,role",id:`eq.${a.employee_id}`,limit:"1"})),age=b.remember?2592000:28800,s=await token({sub:a.employee_id,iat:Math.floor(now/1000),exp:Math.floor(now/1000)+age});return json({user:{identifier:a.identifier,role:a.role,...p?.[0]}},200,{"Set-Cookie":cookieHeader(s,age)})}
if(action==="logout"&&req.method==="POST")return json({ok:true},200,{"Set-Cookie":cookieHeader("",0)});
const user=await current(req);if(!user)return json({error:"Votre session a expiré. Reconnectez-vous."},401,{"Set-Cookie":cookieHeader("",0)});
if(action==="me"&&req.method==="GET"){const {data}=await db(qp("employees",{select:"first_name,last_name,role",id:`eq.${user.employee_id}`,limit:"1"}));return json({user:{...user,...data?.[0]}})}
if(action==="dashboard"&&req.method==="GET")return json(await dashboard(user));
if(action==="change-password"&&req.method==="POST"){const b=await readBody(req);if(typeof b.new_password!=="string"||b.new_password.length<12)return json({error:"Le nouveau mot de passe doit contenir au moins 12 caractères."},400);const {data}=await db(qp("hr_accounts",{select:"password_hash",employee_id:`eq.${user.employee_id}`,limit:"1"}));if(!data?.[0]||!await verifyPassword(String(b.current_password||""),data[0].password_hash))return json({error:"Mot de passe actuel incorrect."},401);await db(qp("hr_accounts",{employee_id:`eq.${user.employee_id}`}),"PATCH",{password_hash:await hashPassword(b.new_password)});return json({ok:true})}
if(action==="leave"&&req.method==="POST"){const b=await readBody(req),start=String(b.start_date||""),end=String(b.end_date||"");if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end)||start>end||workdays(start,end)<1||workdays(start,end)>60)return json({error:"Choisissez des dates valides, jusqu’à 60 jours ouvrés."},400);const {data:overlap}=await db(qp("leave_requests",{select:"id",employee_id:`eq.${user.employee_id}`,status:"in.(pending,approved)",start_date:`lte.${end}`,end_date:`gte.${start}`,limit:"1"}));if(overlap.length)return json({error:"Une demande existe déjà sur cette période."},409);await db("leave_requests","POST",{employee_id:user.employee_id,leave_type:String(b.leave_type||"Congés payés").slice(0,80),start_date:start,end_date:end,days:workdays(start,end),status:"pending"});return json({ok:true},201)}
if(action==="leave-status"&&req.method==="POST"){if(!["admin","manager"].includes(user.role))return json({error:"Vous n’avez pas les droits nécessaires."},403);const b=await readBody(req);if(!b.id||!["approved","rejected"].includes(b.status))return json({error:"Décision invalide."},400);const id=String(b.id).replace(/[^\w-]/g,"");const result=await db(qp("leave_requests",{id:`eq.${id}`,status:"eq.pending"}),"PATCH",{status:b.status,reviewed_by:user.employee_id,reviewed_at:new Date().toISOString()});return result.data?.length?json({ok:true}):json({error:"Cette demande n’est plus en attente."},404)}
if(action==="add-employee"&&req.method==="POST"){if(user.role!=="admin")return json({error:"Seule l’administration RH peut créer un profil."},403);const b=await readBody(req);for(const f of ["identifier","password","first_name","last_name","staff_number"])if(typeof b[f]!=="string"||b[f].trim().length<2)return json({error:`Le champ ${f} est requis.`},400);if(b.password.length<12)return json({error:"Le mot de passe doit contenir au moins 12 caractères."},400);const identifier=b.identifier.trim().toUpperCase(),role=["employee","manager"].includes(b.role)?b.role:"employee",created=await db("employees","POST",{staff_number:b.staff_number.trim(),first_name:b.first_name.trim(),last_name:b.last_name.trim(),job_title:String(b.job_title||"").trim()||null,department:String(b.department||"").trim()||null,contract_type:String(b.contract_type||"CDI"),start_date:b.start_date||new Date().toISOString().slice(0,10),status:"active",role,leave_balance:25}),e=created.data[0];try{await db("hr_accounts","POST",{employee_id:e.id,identifier,password_hash:await hashPassword(b.password),role,enabled:true})}catch(error){await db(qp("employees",{id:`eq.${e.id}`}),"DELETE");throw error}return json({employee_id:e.id,identifier},201)}
return json({error:"Action non disponible."},404);
}catch(error){console.error("[noria]",error?.message||error);return json({error:error?.status&&error.status<500?error.message:"Le service est momentanément indisponible."},error?.status&&error.status<500?error.status:503)}});

